     3→export async function getAnalyticsSummary(shop: string, days: number = 30) {
     4→  const from = new Date();
     5→  from.setDate(from.getDate() - days);
     6→  const prevFrom = new Date();
     7→  prevFrom.setDate(prevFrom.getDate() - days * 2);
