    17→    db.quizResponse.count({
    18→      where: {
    19→        shop,
    20→        completedAt: { not: null },
    21→        createdAt: { gte: from },
    22→      },
    23→    }),
    24→    db.quizResponse.count({
    25→      where: { shop, createdAt: { gte: from } },
    26→    }),
    27→    db.quizResponse.aggregate({
    28→      where: { shop, createdAt: { gte: from } },
    29→      _sum: { revenue: true },
    30→    }),
    31→    db.quizResponse.count({
    32→      where: {
    33→        shop,
    34→        email: { not: null },
    35→        createdAt: { gte: from },
    36→      },
    37→    }),
    38→    db.quizResponse.count({
    39→      where: {
    40→        shop,
    41→        completedAt: { not: null },
    42→        createdAt: { gte: prevFrom, lt: from },
    43→      },
    44→    }),
    45→    db.quiz.findMany({
    46→      where: { shop, status: { not: "archived" } },
    47→      select: { id: true, title: true, completions: true },
    48→      orderBy: { completions: "desc" },
    49→      take: 5,
    50→    }),
    51→  ]);
    52→
