    54→  const completionRate = starts > 0 ? completions / starts : 0;
    55→  const trendDelta =
    56→    prevCompletions > 0
    57→      ? (((completions - prevCompletions) / prevCompletions) * 100).toFixed(1)
    58→      : "0";
    59→
    60→  return {
    61→    completions,
    62→    starts,
    63→    completionRate,
    64→    revenue: totalRevenue,
    65→    emailsCaptured: emails,
