    74→  from.setHours(0, 0, 0, 0);
    75→
    76→  const responses = await db.quizResponse.findMany({
    77→    where: { shop, createdAt: { gte: from } },
    78→    select: { createdAt: true, completedAt: true },
    79→  });
    80→
    81→  const byDate: Record<string, { started: number; completed: number }> = {};
    82→  for (const r of responses) {
