import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  Select,
  Text,
  BlockStack,
  InlineStack,
  DataTable,
  Badge,
  ProgressBar,
  Divider,
  InlineGrid,
  SkeletonPage,
  SkeletonBodyText,
  SkeletonDisplayText,
  EmptyState,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import {
  getAnalyticsSummary,
  getDailyStats,
} from "~/services/analytics.server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  const days = parseInt(
    new URL(request.url).searchParams.get("days") ?? "7",
    10,
  );
  const safeDays = Number.isFinite(days) && days > 0 ? days : 7;

  const [summary, dailyStats] = await Promise.all([
    getAnalyticsSummary(session.shop, safeDays),
    getDailyStats(session.shop, safeDays),
  ]);

  return { summary, dailyStats, days: safeDays };
};

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

export function HydrateFallback() {
  return (
    <SkeletonPage title="Analytics" primaryAction>
      <Layout>
        <Layout.Section>
          <BlockStack gap="400">
            <SkeletonDisplayText size="small" />
            <SkeletonBodyText lines={6} />
          </BlockStack>
        </Layout.Section>
      </Layout>
    </SkeletonPage>
  );
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function formatRevenue(value: number): string {
  return `$${value.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

function trendBadge(changeStr: string) {
  // changeStr comes from the service as e.g. "+12.3%" or "-5.0%"
  const isPositive = changeStr.startsWith("+");
  const isNegative = changeStr.startsWith("-");
  const tone = isPositive ? "success" : isNegative ? "critical" : "info";
  return <Badge tone={tone}>{changeStr}</Badge>;
}

// ─────────────────────────────────────────────────────────────────────────────

export default function AnalyticsPage() {
  const { summary, dailyStats, days } = useLoaderData<typeof loader>();
  const navigate = useNavigate();

  const dateRangeOptions = [
    { label: "Last 7 days", value: "7" },
    { label: "Last 30 days", value: "30" },
    { label: "Last 90 days", value: "90" },
  ];

  function handleDaysChange(value: string) {
    navigate(`?days=${value}`);
  }

  // Map service return shape to display values
  const totalRevenue = summary.revenue;
  const totalCompletions = summary.completions;
  const completionRate = summary.completionRate;
  const emailsCaptured = summary.emailsCaptured;
  // The service provides a single trend string for completions; reuse for all
  // badges — the individual change metrics aren't computed server-side yet.
  const completionsTrend = summary.trend;

  // Daily stats table rows
  const dailyRows = dailyStats.map((day) => [
    day.date,
    day.started.toLocaleString(),
    day.completed.toLocaleString(),
    day.started > 0
      ? `${Math.round((day.completed / day.started) * 100)}%`
      : "—",
  ]);

  const totalStarted = dailyStats.reduce((s, d) => s + d.started, 0);
  const totalCompleted = dailyStats.reduce((s, d) => s + d.completed, 0);
  const overallRate =
    totalStarted > 0
      ? `${Math.round((totalCompleted / totalStarted) * 100)}%`
      : "—";

  return (
    <Page title="Analytics" subtitle="Track your quiz performance">
      <BlockStack gap="600">
        {/* Date Range Filter */}
        <InlineStack align="end">
          <div style={{ width: 200 }}>
            <Select
              label="Date range"
              labelHidden
              options={dateRangeOptions}
              value={String(days)}
              onChange={handleDaysChange}
            />
          </div>
        </InlineStack>

        {/* Summary Stats Row */}
        <InlineGrid columns={{ xs: 1, sm: 2, lg: 4 }} gap="400">
          <Card>
            <BlockStack gap="200">
              <Text as="p" variant="bodyMd" tone="subdued">
                Attributed Revenue
              </Text>
              <InlineStack align="space-between" blockAlign="end">
                <Text as="p" variant="headingXl" fontWeight="bold">
                  {formatRevenue(totalRevenue)}
                </Text>
                {trendBadge(completionsTrend)}
              </InlineStack>
              <Text as="p" variant="bodySm" tone="subdued">
                vs. previous period
              </Text>
            </BlockStack>
          </Card>

          <Card>
            <BlockStack gap="200">
              <Text as="p" variant="bodyMd" tone="subdued">
                Quiz Completions
              </Text>
              <InlineStack align="space-between" blockAlign="end">
                <Text as="p" variant="headingXl" fontWeight="bold">
                  {totalCompletions.toLocaleString()}
                </Text>
                {trendBadge(completionsTrend)}
              </InlineStack>
              <Text as="p" variant="bodySm" tone="subdued">
                vs. previous period
              </Text>
            </BlockStack>
          </Card>

          <Card>
            <BlockStack gap="200">
              <Text as="p" variant="bodyMd" tone="subdued">
                Conversion Rate
              </Text>
              <InlineStack align="space-between" blockAlign="end">
                <Text as="p" variant="headingXl" fontWeight="bold">
                  {`${(completionRate * 100).toFixed(1)}%`}
                </Text>
                {trendBadge(completionsTrend)}
              </InlineStack>
              <Text as="p" variant="bodySm" tone="subdued">
                vs. previous period
              </Text>
            </BlockStack>
          </Card>

          <Card>
            <BlockStack gap="200">
              <Text as="p" variant="bodyMd" tone="subdued">
                Emails Captured
              </Text>
              <InlineStack align="space-between" blockAlign="end">
                <Text as="p" variant="headingXl" fontWeight="bold">
                  {emailsCaptured.toLocaleString()}
                </Text>
                {trendBadge(completionsTrend)}
              </InlineStack>
              <Text as="p" variant="bodySm" tone="subdued">
                vs. previous period
              </Text>
            </BlockStack>
          </Card>
        </InlineGrid>

        {/* Charts Section */}
        <Layout>
          <Layout.Section>
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd">
                  Completions Over Time
                </Text>
                {dailyRows.length === 0 ? (
                  <EmptyState
                    heading="No activity in this period"
                    image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
                  >
                    <p>
                      Quiz responses will appear here once shoppers start taking
                      your quizzes.
                    </p>
                  </EmptyState>
                ) : (
                  <DataTable
                    columnContentTypes={["text", "numeric", "numeric", "numeric"]}
                    headings={[
                      "Date",
                      "Started",
                      "Completed",
                      "Completion Rate",
                    ]}
                    rows={dailyRows}
                    totals={[
                      "",
                      totalStarted.toLocaleString(),
                      totalCompleted.toLocaleString(),
                      overallRate,
                    ]}
                    showTotalsInFooter
                  />
                )}
              </BlockStack>
            </Card>
          </Layout.Section>

          <Layout.Section variant="oneThird">
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd">
                  Top Performing Quizzes
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Install quiz analytics tracking to see per-quiz performance
                  data.
                </Text>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>

        {/* Response Breakdown Table */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd">
              Response Breakdown
            </Text>
            {dailyRows.length === 0 ? (
              <EmptyState
                heading="No data yet"
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
              >
                <p>Response breakdown will populate once quizzes are active.</p>
              </EmptyState>
            ) : (
              <DataTable
                columnContentTypes={[
                  "text",
                  "numeric",
                  "numeric",
                  "numeric",
                ]}
                headings={["Date", "Started", "Completed", "Completion Rate"]}
                rows={dailyRows}
                sortable={[true, true, true, true]}
              />
            )}
          </BlockStack>
        </Card>

        {/* Popular Answers placeholder */}
        <Card>
          <BlockStack gap="500">
            <Text as="h2" variant="headingMd">
              Popular Answers
            </Text>
            <Divider />
            <Text as="p" variant="bodyMd" tone="subdued">
              Per-question answer breakdowns will be available once your quizzes
              have collected responses.
            </Text>
          </BlockStack>
        </Card>
      </BlockStack>
    </Page>
  );
}

